-- Seed Spring Cloud Config JDBC in schema lex_config (PROFILE default|dev|prod).
-- Fuente de verdad runtime: lex_config.PROPERTIES via config-server jdbc.
-- Cambios posteriores: nuevas migraciones bajo db/migration/lex_config/ (no YAML).

-- Reemplaza el catálogo master completo (default/dev/prod).
DELETE FROM PROPERTIES WHERE LABEL = 'master' AND PROFILE IN ('default', 'dev', 'prod');

